ON CONFLICT (external_id) WHERE external_id IS NOT NULL DO UPDATE SET
  name = EXCLUDED.name, category = EXCLUDED.category, kcal = EXCLUDED.kcal,
  protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g,
  fiber_g = EXCLUDED.fiber_g, saturated_fat_g = EXCLUDED.saturated_fat_g, sodium_mg = EXCLUDED.sodium_mg,
  cholesterol_mg = EXCLUDED.cholesterol_mg, calcium_mg = EXCLUDED.calcium_mg, iron_mg = EXCLUDED.iron_mg,
  magnesium_mg = EXCLUDED.magnesium_mg, phosphorus_mg = EXCLUDED.phosphorus_mg,
  potassium_mg = EXCLUDED.potassium_mg, zinc_mg = EXCLUDED.zinc_mg,
  vitamin_a_mcg = EXCLUDED.vitamin_a_mcg, vitamin_c_mg = EXCLUDED.vitamin_c_mg,
  popularity = EXCLUDED.popularity, is_staple = EXCLUDED.is_staple;

-- Classifica os 25 alimentos do seed original, que nasceram sem categoria.
UPDATE public.foods SET category = CASE
  WHEN name ~* '(frango|carne|patinho|tilápia|salmão|atum|peixe|peru)' THEN 'protein_meat'
  WHEN name ~* 'ovo' THEN 'protein_egg'
  WHEN name ~* '(leite|iogurte|queijo|requeijão|whey)' THEN 'dairy'
  WHEN name ~* '(feijão|lentilha|grão-de-bico|soja|ervilha)' THEN 'legume'
  WHEN name ~* '(arroz|aveia|pão|macarrão|tapioca|farinha|cuscuz|granola)' THEN 'grain'
  WHEN name ~* '(batata|mandioca|inhame)' THEN 'tuber'
  WHEN name ~* '(banana|maçã|laranja|mamão|abacate|morango|uva|manga|melancia)' THEN 'fruit'
  WHEN name ~* '(azeite|óleo|castanha|amendoim|amêndoa|nozes|pasta de)' THEN 'fat'
  WHEN name ~* '(brócolis|alface|tomate|cenoura|couve|abobrinha|espinafre)' THEN 'vegetable'
  ELSE 'other'
END::public.food_category_t
WHERE owner_id IS NULL AND external_id IS NULL AND category = 'other';

UPDATE public.foods SET is_staple = TRUE, popularity = 85
WHERE owner_id IS NULL AND external_id IS NULL AND category <> 'other';
